PLAN = json.loads('{"admission_primary": 0.604, "blend": {"aggregations": [{"method": "rank_average", "scope": "per_user"}, {"method": "rank_average", "scope": "global"}], "weights": "equal"}, "full_member_limit": 3, "members": [{"config": {"epochs": 14}, "family": "regularized-dcn-package", "member_id": "regularized-dcn-package", "script_source": "logs/run_f9/nodes/001.py", "seed": 42}, {"code": "import argparse\\nimport csv\\nimport gc\\nimport importlib.util\\nimport json\\nimport math\\nimport os\\n\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\n\\n\\ndef load_base():\\n    paths = [os.path.join(os.getcwd(), \'logs\', \'run_f9\', \'nodes\', \'001.py\')]\\n    here = os.path.abspath(__file__)\\n    for _ in range(8):\\n        here = os.path.dirname(here)\\n        paths.append(os.path.join(here, \'logs\', \'run_f9\', \'nodes\', \'001.py\'))\\n    for path in paths:\\n        if os.path.isfile(path):\\n            spec = importlib.util.spec_from_file_location(\'champion_base_temporal\', path)\\n            module = importlib.util.module_from_spec(spec)\\n            spec.loader.exec_module(module)\\n            return module\\n    raise FileNotFoundError(\'champion script unavailable\')\\n\\n\\ndef hour_bucket(values):\\n    out = np.zeros(len(values), dtype=np.int16)\\n    for i, value in enumerate(values):\\n        if isinstance(value, bytes):\\n            value = value.decode(\'utf-8\')\\n        try:\\n            number = int(float(str(value).strip()))\\n            out[i] = (number // 100) % 24\\n        except ValueError:\\n            out[i] = 0\\n    return out\\n\\n\\ndef predict(base, model, xv, device):\\n    return base.predict_model(model, xv, device)\\n\\n\\ndef train(base, xt, yt, xv, train_data, val, total_dim, evaluator, device, seed, epochs):\\n    torch.manual_seed(seed)\\n    np.random.seed(seed)\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(seed)\\n    model = base.DCNHybrid(total_dim, xt.shape[1], 16, 128, 1, 0.30).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=9e-4, weight_decay=3e-4)\\n    inverse, eligible_pos, neg_order, neg_offsets, neg_counts = base.make_pair_pool(train_data[\'user\'], train_data[\'y\'])\\n    days = train_data[\'days\'].astype(np.float32)\\n    hours = train_data[\'hours\'].astype(np.int16)\\n    weights_np = np.exp2(-days / 7.0).astype(np.float32)\\n    weights_np /= max(float(weights_np.mean()), 1e-8)\\n    weights = torch.from_numpy(weights_np)\\n    rng = np.random.RandomState(seed + 8123)\\n    n = len(yt)\\n    best_primary = -1.0\\n    best_scores = None\\n    best_metrics = None\\n    best_checkpoint = 0.0\\n    curve = []\\n    halves = max(2, 2 * epochs)\\n    perm = None\\n    for half in range(halves):\\n        completed = half * 0.5\\n        lr = 9e-4 * (0.52 ** int(math.floor(completed + 1e-9)))\\n        for group in opt.param_groups:\\n            group[\'lr\'] = lr\\n        if half % 2 == 0:\\n            perm = torch.randperm(n)\\n        midpoint = (n + 1) // 2\\n        phase = perm[:midpoint] if half % 2 == 0 else perm[midpoint:]\\n        model.train()\\n        loss_sum = 0.0\\n        steps = 0\\n        for start in range(0, len(phase), 16384):\\n            idx = phase[start:start + 16384]\\n            b = len(idx)\\n            q = max(1, b // 2) if len(eligible_pos) else 0\\n            if q:\\n                chosen = rng.randint(0, len(eligible_pos), size=q)\\n                pidx = eligible_pos[chosen]\\n                groups = inverse[pidx]\\n                offsets = (rng.random_sample(q) * neg_counts[groups]).astype(np.int64)\\n                nidx = neg_order[neg_offsets[groups] + offsets]\\n                pt = torch.from_numpy(pidx)\\n                nt = torch.from_numpy(nidx)\\n                all_x = torch.cat((xt[idx], xt[pt], xt[nt]), dim=0).to(device, non_blocking=True)\\n            else:\\n                pt = nt = None\\n                all_x = xt[idx].to(device, non_blocking=True)\\n            logits = model(all_x)\\n            yb = yt[idx].to(device, non_blocking=True)\\n            wb = weights[idx].to(device, non_blocking=True)\\n            point = F.binary_cross_entropy_with_logits(logits[:b], yb, reduction=\'none\')\\n            point_loss = (point * wb).sum() / wb.sum().clamp_min(1e-8)\\n            if q:\\n                pair = F.softplus(-(logits[b:b + q] - logits[b + q:b + 2 * q]))\\n                day_distance = np.abs(days[pidx] - days[nidx])\\n                hour_distance = np.abs(hours[pidx].astype(np.int32) - hours[nidx].astype(np.int32))\\n                hour_distance = np.minimum(hour_distance, 24 - hour_distance)\\n                same_tab = (train_data[\'X\'][pidx, 3] == train_data[\'X\'][nidx, 3]).astype(np.float32)\\n                kernel_np = 0.50 + np.exp(-day_distance / 7.0) * (0.5 + 0.5 * np.exp(-hour_distance / 4.0)) * (1.0 + 0.35 * same_tab)\\n                kernel_np = kernel_np.astype(np.float32)\\n                kernel_np /= max(float(kernel_np.mean()), 1e-8)\\n                kernel = torch.from_numpy(kernel_np).to(device, non_blocking=True)\\n                pair_w = weights[pt].to(device, non_blocking=True) * kernel\\n                pair_loss = (pair * pair_w).sum() / pair_w.sum().clamp_min(1e-8)\\n                loss = 0.5 * point_loss + 0.5 * pair_loss\\n            else:\\n                loss = point_loss\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            loss_sum += float(loss.detach().cpu())\\n            steps += 1\\n        scores = predict(base, model, xv, device)\\n        metrics = base.metric_dict(evaluator, val[\'user\'], val[\'y\'], scores)\\n        checkpoint = (half + 1) * 0.5\\n        curve.append({\'checkpoint\': checkpoint, \'train_loss\': loss_sum / max(steps, 1), \'lr\': lr, \'primary\': metrics[\'primary\'], \'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\']})\\n        if metrics[\'primary\'] > best_primary + 1e-8:\\n            best_primary = metrics[\'primary\']\\n            best_scores = scores.copy()\\n            best_metrics = metrics\\n            best_checkpoint = checkpoint\\n    del model, opt\\n    gc.collect()\\n    if device.type == \'cuda\':\\n        torch.cuda.empty_cache()\\n    return best_scores, best_metrics, best_checkpoint, curve\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\'--data-dir\', required=True)\\n    ap.add_argument(\'--out-dir\', required=True)\\n    ap.add_argument(\'--seed\', type=int, default=42)\\n    ap.add_argument(\'--epochs\', type=int, default=12)\\n    args = ap.parse_args()\\n    os.makedirs(args.out_dir, exist_ok=True)\\n    base = load_base()\\n    torch.manual_seed(args.seed)\\n    np.random.seed(args.seed)\\n    if torch.cuda.is_available():\\n        device = torch.device(\'cuda\')\\n        torch.cuda.manual_seed_all(args.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    else:\\n        device = torch.device(\'cpu\')\\n    train_data, val, field_dims, evaluator, source = base.load_data(args.data_dir)\\n    npz_path = os.path.join(args.data_dir, \'train.npz\')\\n    if os.path.exists(npz_path):\\n        with np.load(npz_path) as data:\\n            train_data[\'hours\'] = hour_bucket(np.asarray(data[\'hourmin\']))\\n    else:\\n        hours = []\\n        with open(os.path.join(args.data_dir, \'train.csv\'), \'r\', newline=\'\') as fh:\\n            for row in csv.DictReader(fh):\\n                hours.append(row[\'hourmin\'])\\n        train_data[\'hours\'] = hour_bucket(np.asarray(hours))\\n    xt = torch.from_numpy(train_data[\'X\'].astype(np.int64, copy=False))\\n    yt = torch.from_numpy(train_data[\'y\'].astype(np.float32, copy=False))\\n    xv = torch.from_numpy(val[\'X\'].astype(np.int64, copy=False))\\n    epochs = max(1, args.epochs)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    if smoke is not None:\\n        epochs = max(1, min(epochs, int(smoke)))\\n    scores, metrics, checkpoint, curve = train(base, xt, yt, xv, train_data, val, int(field_dims.sum()), evaluator, device, args.seed, epochs)\\n    assert np.isfinite(scores).all() and float(np.std(scores)) > 0.0\\n    payload = {\'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\'], \'primary\': metrics[\'primary\'], \'family\': \'temporal-pair-kernel\', \'seed\': args.seed, \'best_checkpoint\': checkpoint, \'history\': curve, \'data_source\': source}\\n    with open(os.path.join(args.out_dir, \'metrics.json\'), \'w\') as fh:\\n        json.dump(payload, fh)\\n    with open(os.path.join(args.out_dir, \'progress.log\'), \'a\') as fh:\\n        fh.write(json.dumps({\'family\': \'temporal-pair-kernel\', \'seed\': args.seed, \'primary\': metrics[\'primary\']}, sort_keys=True) + chr(10))\\n    with open(os.path.join(args.out_dir, \'predictions.csv\'), \'w\', newline=\'\') as fh:\\n        writer = csv.writer(fh)\\n        writer.writerow([\'row_id\', \'user_id\', \'video_id\', \'score\'])\\n        for i, score in enumerate(scores):\\n            writer.writerow([i, val[\'user\'][i], val[\'video_out\'][i], format(float(score), \'.8g\')])\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {"epochs": 12}, "family": "temporal-pair-kernel", "member_id": "temporal-pair-kernel", "seed": 44}, {"code": "import argparse\\nimport collections\\nimport csv\\nimport gc\\nimport importlib.util\\nimport json\\nimport math\\nimport os\\n\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\n\\n\\ndef load_base():\\n    paths = [os.path.join(os.getcwd(), \'logs\', \'run_f9\', \'nodes\', \'001.py\')]\\n    here = os.path.abspath(__file__)\\n    for _ in range(8):\\n        here = os.path.dirname(here)\\n        paths.append(os.path.join(here, \'logs\', \'run_f9\', \'nodes\', \'001.py\'))\\n    for path in paths:\\n        if os.path.isfile(path):\\n            spec = importlib.util.spec_from_file_location(\'champion_base_sequence\', path)\\n            module = importlib.util.module_from_spec(spec)\\n            spec.loader.exec_module(module)\\n            return module\\n    raise FileNotFoundError(\'champion script unavailable\')\\n\\n\\nclass SeqDeepFM(torch.nn.Module):\\n    def __init__(self, total_dim, fields, k=16, hidden=128, length=8, dropout=0.30):\\n        super().__init__()\\n        self.emb = torch.nn.Embedding(total_dim, k)\\n        self.lin = torch.nn.Embedding(total_dim, 1)\\n        self.bias = torch.nn.Parameter(torch.zeros(1))\\n        self.position = torch.nn.Embedding(length, k)\\n        width = fields * k\\n        self.deep = torch.nn.Sequential(torch.nn.Linear(width, hidden), torch.nn.ReLU(), torch.nn.Dropout(dropout), torch.nn.Linear(hidden, 64), torch.nn.ReLU(), torch.nn.Dropout(dropout), torch.nn.Linear(64, 1))\\n        self.sequence = torch.nn.Sequential(torch.nn.Linear(width + 2 * k, hidden), torch.nn.ReLU(), torch.nn.Dropout(dropout), torch.nn.Linear(hidden, 64), torch.nn.ReLU(), torch.nn.Dropout(dropout), torch.nn.Linear(64, 1))\\n        self.norm = torch.nn.LayerNorm(k)\\n        self.drop = torch.nn.Dropout(dropout)\\n        torch.nn.init.normal_(self.emb.weight, std=0.01)\\n        torch.nn.init.normal_(self.position.weight, std=0.01)\\n        torch.nn.init.zeros_(self.lin.weight)\\n\\n    def forward(self, x, history):\\n        e = self.drop(self.emb(x))\\n        summed = e.sum(1)\\n        fm = 0.5 * (summed * summed - (e * e).sum(1)).sum(1)\\n        flat = e.reshape(e.shape[0], -1)\\n        deep = self.deep(flat).squeeze(1)\\n        query = self.norm(e[:, 1, :])\\n        mask = history.ne(0)\\n        positions = torch.arange(history.shape[1], device=history.device).unsqueeze(0)\\n        hist = self.emb(history) + self.position(positions)\\n        hist = self.norm(hist) * mask.unsqueeze(-1)\\n        attention = (hist * query.unsqueeze(1)).sum(-1) / math.sqrt(query.shape[-1])\\n        attention = attention.masked_fill(~mask, -1e4)\\n        attention = torch.softmax(attention, dim=1) * mask\\n        attention = attention / attention.sum(1, keepdim=True).clamp_min(1e-8)\\n        pooled = (hist * attention.unsqueeze(-1)).sum(1)\\n        seq = self.sequence(torch.cat((flat, pooled, query), dim=1)).squeeze(1)\\n        linear = self.lin(x).sum((1, 2))\\n        return self.bias + linear + fm + deep + seq\\n\\n\\ndef build_histories(train_data, val, length):\\n    n = len(train_data[\'y\'])\\n    train_hist = np.zeros((n, length), dtype=np.int64)\\n    tails = {}\\n    for i, user in enumerate(train_data[\'user\']):\\n        queue = tails.get(user)\\n        if queue is None:\\n            queue = collections.deque(maxlen=length)\\n            tails[user] = queue\\n        if queue:\\n            values = np.asarray(queue, dtype=np.int64)\\n            train_hist[i, -len(values):] = values\\n        queue.append(int(train_data[\'X\'][i, 1]))\\n    val_hist = np.zeros((len(val[\'y\']), length), dtype=np.int64)\\n    for i, user in enumerate(val[\'user\']):\\n        queue = tails.get(user)\\n        if queue:\\n            values = np.asarray(queue, dtype=np.int64)\\n            val_hist[i, -len(values):] = values\\n    return torch.from_numpy(train_hist), torch.from_numpy(val_hist)\\n\\n\\ndef predict(model, xv, hv, device):\\n    model.eval()\\n    pieces = []\\n    with torch.no_grad():\\n        for start in range(0, len(xv), 65536):\\n            xb = xv[start:start + 65536].to(device, non_blocking=True)\\n            hb = hv[start:start + 65536].to(device, non_blocking=True)\\n            pieces.append(model(xb, hb).detach().cpu().numpy())\\n    return np.concatenate(pieces).astype(np.float64)\\n\\n\\ndef train(base, xt, yt, ht, xv, hv, train_data, val, total_dim, evaluator, device, seed, epochs):\\n    torch.manual_seed(seed)\\n    np.random.seed(seed)\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(seed)\\n    model = SeqDeepFM(total_dim, xt.shape[1]).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=8e-4, weight_decay=4e-4)\\n    inverse, eligible_pos, neg_order, neg_offsets, neg_counts = base.make_pair_pool(train_data[\'user\'], train_data[\'y\'])\\n    recency_np = np.exp2(-train_data[\'days\'] / 7.0).astype(np.float32)\\n    recency_np /= max(float(recency_np.mean()), 1e-8)\\n    recency = torch.from_numpy(recency_np)\\n    rng = np.random.RandomState(seed + 1907)\\n    n = len(yt)\\n    best_primary = -1.0\\n    best_scores = None\\n    best_metrics = None\\n    best_checkpoint = 0.0\\n    curve = []\\n    halves = max(2, 2 * epochs)\\n    perm = None\\n    for half in range(halves):\\n        completed = half * 0.5\\n        lr = 8e-4 * (0.55 ** int(math.floor(completed + 1e-9)))\\n        for group in opt.param_groups:\\n            group[\'lr\'] = lr\\n        if half % 2 == 0:\\n            perm = torch.randperm(n)\\n        midpoint = (n + 1) // 2\\n        phase = perm[:midpoint] if half % 2 == 0 else perm[midpoint:]\\n        model.train()\\n        loss_sum = 0.0\\n        steps = 0\\n        for start in range(0, len(phase), 12288):\\n            idx = phase[start:start + 12288]\\n            b = len(idx)\\n            q = max(1, b // 2) if len(eligible_pos) else 0\\n            if q:\\n                selected = rng.randint(0, len(eligible_pos), size=q)\\n                pidx = eligible_pos[selected]\\n                groups = inverse[pidx]\\n                offsets = (rng.random_sample(q) * neg_counts[groups]).astype(np.int64)\\n                nidx = neg_order[neg_offsets[groups] + offsets]\\n                pt = torch.from_numpy(pidx)\\n                nt = torch.from_numpy(nidx)\\n                all_x = torch.cat((xt[idx], xt[pt], xt[nt]), dim=0).to(device, non_blocking=True)\\n                all_h = torch.cat((ht[idx], ht[pt], ht[nt]), dim=0).to(device, non_blocking=True)\\n            else:\\n                pt = nt = None\\n                all_x = xt[idx].to(device, non_blocking=True)\\n                all_h = ht[idx].to(device, non_blocking=True)\\n            logits = model(all_x, all_h)\\n            yb = yt[idx].to(device, non_blocking=True)\\n            wb = recency[idx].to(device, non_blocking=True)\\n            point = F.binary_cross_entropy_with_logits(logits[:b], yb, reduction=\'none\')\\n            point_loss = (point * wb).sum() / wb.sum().clamp_min(1e-8)\\n            if q:\\n                pair = F.softplus(-(logits[b:b + q] - logits[b + q:b + 2 * q]))\\n                pair_w = recency[pt].to(device, non_blocking=True)\\n                pair_loss = (pair * pair_w).sum() / pair_w.sum().clamp_min(1e-8)\\n                loss = 0.55 * point_loss + 0.45 * pair_loss\\n            else:\\n                loss = point_loss\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            loss_sum += float(loss.detach().cpu())\\n            steps += 1\\n        scores = predict(model, xv, hv, device)\\n        metrics = base.metric_dict(evaluator, val[\'user\'], val[\'y\'], scores)\\n        checkpoint = (half + 1) * 0.5\\n        curve.append({\'checkpoint\': checkpoint, \'train_loss\': loss_sum / max(steps, 1), \'lr\': lr, \'primary\': metrics[\'primary\'], \'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\']})\\n        if metrics[\'primary\'] > best_primary + 1e-8:\\n            best_primary = metrics[\'primary\']\\n            best_scores = scores.copy()\\n            best_metrics = metrics\\n            best_checkpoint = checkpoint\\n    del model, opt\\n    gc.collect()\\n    if device.type == \'cuda\':\\n        torch.cuda.empty_cache()\\n    return best_scores, best_metrics, best_checkpoint, curve\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\'--data-dir\', required=True)\\n    ap.add_argument(\'--out-dir\', required=True)\\n    ap.add_argument(\'--seed\', type=int, default=42)\\n    ap.add_argument(\'--epochs\', type=int, default=12)\\n    args = ap.parse_args()\\n    os.makedirs(args.out_dir, exist_ok=True)\\n    base = load_base()\\n    torch.manual_seed(args.seed)\\n    np.random.seed(args.seed)\\n    if torch.cuda.is_available():\\n        device = torch.device(\'cuda\')\\n        torch.cuda.manual_seed_all(args.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    else:\\n        device = torch.device(\'cpu\')\\n    train_data, val, field_dims, evaluator, source = base.load_data(args.data_dir)\\n    xt = torch.from_numpy(train_data[\'X\'].astype(np.int64, copy=False))\\n    yt = torch.from_numpy(train_data[\'y\'].astype(np.float32, copy=False))\\n    xv = torch.from_numpy(val[\'X\'].astype(np.int64, copy=False))\\n    ht, hv = build_histories(train_data, val, 8)\\n    epochs = max(1, args.epochs)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    if smoke is not None:\\n        epochs = max(1, min(epochs, int(smoke)))\\n    scores, metrics, checkpoint, curve = train(base, xt, yt, ht, xv, hv, train_data, val, int(field_dims.sum()), evaluator, device, args.seed, epochs)\\n    assert np.isfinite(scores).all() and float(np.std(scores)) > 0.0\\n    payload = {\'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\'], \'primary\': metrics[\'primary\'], \'family\': \'seq-deepfm-composite\', \'seed\': args.seed, \'best_checkpoint\': checkpoint, \'history\': curve, \'history_length\': 8, \'data_source\': source}\\n    with open(os.path.join(args.out_dir, \'metrics.json\'), \'w\') as fh:\\n        json.dump(payload, fh)\\n    with open(os.path.join(args.out_dir, \'progress.log\'), \'a\') as fh:\\n        fh.write(json.dumps({\'family\': \'seq-deepfm-composite\', \'seed\': args.seed, \'primary\': metrics[\'primary\']}, sort_keys=True) + chr(10))\\n    with open(os.path.join(args.out_dir, \'predictions.csv\'), \'w\', newline=\'\') as fh:\\n        writer = csv.writer(fh)\\n        writer.writerow([\'row_id\', \'user_id\', \'video_id\', \'score\'])\\n        for i, score in enumerate(scores):\\n            writer.writerow([i, val[\'user\'][i], val[\'video_out\'][i], format(float(score), \'.8g\')])\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {"epochs": 12}, "family": "seq-deepfm-composite", "member_id": "seq-deepfm-composite", "seed": 43}, {"code": "import argparse\\nimport csv\\nimport gc\\nimport importlib.util\\nimport json\\nimport math\\nimport os\\n\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\n\\n\\ndef load_base():\\n    paths = [os.path.join(os.getcwd(), \'logs\', \'run_f9\', \'nodes\', \'001.py\')]\\n    here = os.path.abspath(__file__)\\n    for _ in range(8):\\n        here = os.path.dirname(here)\\n        paths.append(os.path.join(here, \'logs\', \'run_f9\', \'nodes\', \'001.py\'))\\n    for path in paths:\\n        if os.path.isfile(path):\\n            spec = importlib.util.spec_from_file_location(\'champion_base_recency_fm\', path)\\n            module = importlib.util.module_from_spec(spec)\\n            spec.loader.exec_module(module)\\n            return module\\n    raise FileNotFoundError(\'champion script unavailable\')\\n\\n\\nclass RegularizedFM(torch.nn.Module):\\n    def __init__(self, total_dim, k=16, dropout=0.20):\\n        super().__init__()\\n        self.emb = torch.nn.Embedding(total_dim, k)\\n        self.lin = torch.nn.Embedding(total_dim, 1)\\n        self.bias = torch.nn.Parameter(torch.zeros(1))\\n        self.drop = torch.nn.Dropout(dropout)\\n        self.scale = torch.nn.Parameter(torch.ones(k))\\n        torch.nn.init.normal_(self.emb.weight, std=0.01)\\n        torch.nn.init.zeros_(self.lin.weight)\\n\\n    def forward(self, x):\\n        e = self.drop(self.emb(x)) * self.scale\\n        summed = e.sum(1)\\n        pair = 0.5 * (summed * summed - (e * e).sum(1)).sum(1)\\n        linear = self.lin(x).sum((1, 2))\\n        return self.bias + linear + pair\\n\\n\\ndef predict(model, xv, device):\\n    model.eval()\\n    pieces = []\\n    with torch.no_grad():\\n        for start in range(0, len(xv), 65536):\\n            pieces.append(model(xv[start:start + 65536].to(device, non_blocking=True)).detach().cpu().numpy())\\n    return np.concatenate(pieces).astype(np.float64)\\n\\n\\ndef train(base, xt, yt, xv, train_data, val, total_dim, evaluator, device, seed, epochs):\\n    torch.manual_seed(seed)\\n    np.random.seed(seed)\\n    if device.type == \'cuda\':\\n        torch.cuda.manual_seed_all(seed)\\n    model = RegularizedFM(total_dim).to(device)\\n    opt = torch.optim.AdamW(model.parameters(), lr=1.1e-3, weight_decay=5e-4)\\n    inverse, eligible_pos, neg_order, neg_offsets, neg_counts = base.make_pair_pool(train_data[\'user\'], train_data[\'y\'])\\n    days = train_data[\'days\'].astype(np.float32)\\n    recent_np = np.exp2(-days / 5.0).astype(np.float32)\\n    recent_np = np.clip(recent_np, 0.15, 1.0)\\n    recent_np /= max(float(recent_np.mean()), 1e-8)\\n    recent = torch.from_numpy(recent_np)\\n    rng = np.random.RandomState(seed + 4441)\\n    n = len(yt)\\n    best_primary = -1.0\\n    best_scores = None\\n    best_metrics = None\\n    best_checkpoint = 0.0\\n    curve = []\\n    halves = max(2, 2 * epochs)\\n    perm = None\\n    for half in range(halves):\\n        completed = half * 0.5\\n        lr = 1.1e-3 * (0.50 ** int(math.floor(completed + 1e-9)))\\n        for group in opt.param_groups:\\n            group[\'lr\'] = lr\\n        if half % 2 == 0:\\n            perm = torch.randperm(n)\\n        midpoint = (n + 1) // 2\\n        phase = perm[:midpoint] if half % 2 == 0 else perm[midpoint:]\\n        model.train()\\n        loss_sum = 0.0\\n        steps = 0\\n        for start in range(0, len(phase), 16384):\\n            idx = phase[start:start + 16384]\\n            b = len(idx)\\n            q = max(1, b // 2) if len(eligible_pos) else 0\\n            if q:\\n                selected = rng.randint(0, len(eligible_pos), size=q)\\n                pidx = eligible_pos[selected]\\n                groups = inverse[pidx]\\n                offsets = (rng.random_sample(q) * neg_counts[groups]).astype(np.int64)\\n                nidx = neg_order[neg_offsets[groups] + offsets]\\n                pt = torch.from_numpy(pidx)\\n                nt = torch.from_numpy(nidx)\\n                all_x = torch.cat((xt[idx], xt[pt], xt[nt]), dim=0).to(device, non_blocking=True)\\n            else:\\n                pt = nt = None\\n                all_x = xt[idx].to(device, non_blocking=True)\\n            logits = model(all_x)\\n            yb = yt[idx].to(device, non_blocking=True)\\n            wb = recent[idx].to(device, non_blocking=True)\\n            point = F.binary_cross_entropy_with_logits(logits[:b], yb, reduction=\'none\')\\n            point_loss = (point * wb).sum() / wb.sum().clamp_min(1e-8)\\n            if q:\\n                pair = F.softplus(-(logits[b:b + q] - logits[b + q:b + 2 * q]))\\n                pair_w = recent[pt].to(device, non_blocking=True)\\n                pair_loss = (pair * pair_w).sum() / pair_w.sum().clamp_min(1e-8)\\n                loss = 0.60 * point_loss + 0.40 * pair_loss\\n            else:\\n                loss = point_loss\\n            row_l2 = model.emb(all_x[:b]).pow(2).mean()\\n            loss = loss + 2e-6 * row_l2\\n            opt.zero_grad(set_to_none=True)\\n            loss.backward()\\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)\\n            opt.step()\\n            loss_sum += float(loss.detach().cpu())\\n            steps += 1\\n        scores = predict(model, xv, device)\\n        metrics = base.metric_dict(evaluator, val[\'user\'], val[\'y\'], scores)\\n        checkpoint = (half + 1) * 0.5\\n        curve.append({\'checkpoint\': checkpoint, \'train_loss\': loss_sum / max(steps, 1), \'lr\': lr, \'primary\': metrics[\'primary\'], \'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\']})\\n        if metrics[\'primary\'] > best_primary + 1e-8:\\n            best_primary = metrics[\'primary\']\\n            best_scores = scores.copy()\\n            best_metrics = metrics\\n            best_checkpoint = checkpoint\\n    del model, opt\\n    gc.collect()\\n    if device.type == \'cuda\':\\n        torch.cuda.empty_cache()\\n    return best_scores, best_metrics, best_checkpoint, curve\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\'--data-dir\', required=True)\\n    ap.add_argument(\'--out-dir\', required=True)\\n    ap.add_argument(\'--seed\', type=int, default=42)\\n    ap.add_argument(\'--epochs\', type=int, default=12)\\n    args = ap.parse_args()\\n    os.makedirs(args.out_dir, exist_ok=True)\\n    base = load_base()\\n    torch.manual_seed(args.seed)\\n    np.random.seed(args.seed)\\n    if torch.cuda.is_available():\\n        device = torch.device(\'cuda\')\\n        torch.cuda.manual_seed_all(args.seed)\\n        torch.backends.cudnn.deterministic = True\\n        torch.backends.cudnn.benchmark = False\\n    else:\\n        device = torch.device(\'cpu\')\\n    train_data, val, field_dims, evaluator, source = base.load_data(args.data_dir)\\n    xt = torch.from_numpy(train_data[\'X\'].astype(np.int64, copy=False))\\n    yt = torch.from_numpy(train_data[\'y\'].astype(np.float32, copy=False))\\n    xv = torch.from_numpy(val[\'X\'].astype(np.int64, copy=False))\\n    epochs = max(1, args.epochs)\\n    smoke = os.environ.get(\'SMOKE_EPOCHS\')\\n    if smoke is not None:\\n        epochs = max(1, min(epochs, int(smoke)))\\n    scores, metrics, checkpoint, curve = train(base, xt, yt, xv, train_data, val, int(field_dims.sum()), evaluator, device, args.seed, epochs)\\n    assert np.isfinite(scores).all() and float(np.std(scores)) > 0.0\\n    payload = {\'gauc\': metrics[\'gauc\'], \'ndcg5\': metrics[\'ndcg5\'], \'primary\': metrics[\'primary\'], \'family\': \'recency-weighted-factorization-machine\', \'seed\': args.seed, \'best_checkpoint\': checkpoint, \'history\': curve, \'half_life\': 5.0, \'data_source\': source}\\n    with open(os.path.join(args.out_dir, \'metrics.json\'), \'w\') as fh:\\n        json.dump(payload, fh)\\n    with open(os.path.join(args.out_dir, \'progress.log\'), \'a\') as fh:\\n        fh.write(json.dumps({\'family\': \'recency-weighted-factorization-machine\', \'seed\': args.seed, \'primary\': metrics[\'primary\']}, sort_keys=True) + chr(10))\\n    with open(os.path.join(args.out_dir, \'predictions.csv\'), \'w\', newline=\'\') as fh:\\n        writer = csv.writer(fh)\\n        writer.writerow([\'row_id\', \'user_id\', \'video_id\', \'score\'])\\n        for i, score in enumerate(scores):\\n            writer.writerow([i, val[\'user\'][i], val[\'video_out\'][i], format(float(score), \'.8g\')])\\n\\n\\nif __name__ == \'__main__\':\\n    main()\\n", "config": {"epochs": 12}, "family": "recency-weighted-factorization-machine", "member_id": "recency-weighted-factorization-machine", "seed": 45}], "min_probe_blend_gain": 0.0, "probe_epochs": 2}')
